interface ProjectBudget {
  totalPaid: number;
  effectiveEngineeringRate: number;
  overheadRatio: number;
}

function calculateEngineeringValue(budget: ProjectBudget) {
  const directCodeSpend = budget.totalPaid * (1 - budget.overheadRatio);
  const productiveHours = directCodeSpend / budget.effectiveEngineeringRate;
  return {
    capitalSpentOnCode: directCodeSpend,
    overheadLoss: budget.totalPaid * budget.overheadRatio,
    productiveHours: Math.round(productiveHours)
  };
}

// Agency vs Freelance comparison on a $20,000 MVP budget
const agencyEstimate = calculateEngineeringValue({
  totalPaid: 20000,
  effectiveEngineeringRate: 120,
  overheadRatio: 0.55 // 55% goes to management, sales, and profit margin
});

const freelanceEstimate = calculateEngineeringValue({
  totalPaid: 20000,
  effectiveEngineeringRate: 85,
  overheadRatio: 0.05 // 5% software tooling & hosting fees
});

// Freelancer delivers ~223 engineering hours vs Agency ~75 engineering hours
